const BASELINE_EBNF = "// Lark EBNF Grammar: AutoGrammar Fixed Baseline SQL DSL\n// Covers school management DSL queries (SELECT, INSERT, UPDATE, DELETE, JOIN, AGGREGATE, SUBQUERY)\n\n?start: statement [\";\"]\n\n?statement: select_stmt\n          | insert_stmt\n          | update_stmt\n          | delete_stmt\n\n// --- SELECT STATEMENT ---\nselect_stmt: \"SELECT\"i [distinct_clause] select_list from_clause [where_clause] [groupby_clause] [having_clause] [orderby_clause] [limit_clause]\n\ndistinct_clause: \"DISTINCT\"i\n\nselect_list: select_item (\",\" select_item)*\n\nselect_item: aggregate_expr [alias_clause]\n           | column_ref [alias_clause]\n           | \"*\"\n\nalias_clause: [\"AS\"i] CNAME\n\nfrom_clause: \"FROM\"i table_source (join_clause)*\n\ntable_source: CNAME [\"AS\"i CNAME]\n\njoin_clause: ([\"INNER\"i] \"JOIN\"i | \"LEFT\"i [\"JOIN\"i]) table_source \"ON\"i condition\n\n// --- WHERE & CONDITIONS ---\nwhere_clause: \"WHERE\"i condition\n\n?condition: or_expr\n\n?or_expr: and_expr (\"OR\"i and_expr)*\n\n?and_expr: not_expr (\"AND\"i not_expr)*\n\n?not_expr: \"NOT\"i not_expr -> not_condition\n         | predicate\n\n?predicate: comparison_predicate\n          | in_predicate\n          | between_predicate\n          | like_predicate\n          | null_predicate\n          | \"(\" condition \")\"\n\ncomparison_predicate: expr COMP_OP expr\n\nin_predicate: expr \"IN\"i \"(\" (literal_list | select_stmt) \")\"\n\nbetween_predicate: expr \"BETWEEN\"i expr \"AND\"i expr\n\nlike_predicate: expr \"LIKE\"i STRING\n\nnull_predicate: expr \"IS\"i [\"NOT\"i] \"NULL\"i\n\n// --- EXPRESSIONS ---\n?expr: aggregate_expr\n     | column_ref\n     | literal\n     | \"(\" select_stmt \")\" -> scalar_subquery\n\naggregate_expr: AGG_FUNC \"(\" (column_ref | \"*\" | literal) \")\"\n\ncolumn_ref: [CNAME \".\"] (CNAME | \"*\")\n\nliteral_list: literal (\",\" literal)*\n\n?literal: NUMBER\n        | STRING\n\n// --- GROUP BY, HAVING, ORDER BY, LIMIT ---\ngroupby_clause: \"GROUP\"i \"BY\"i group_item (\",\" group_item)*\ngroup_item: column_ref\n\nhaving_clause: \"HAVING\"i condition\n\norderby_clause: \"ORDER\"i \"BY\"i order_item (\",\" order_item)*\norder_item: column_ref [\"ASC\"i | \"DESC\"i]\n\nlimit_clause: \"LIMIT\"i NUMBER\n\n// --- INSERT STATEMENT ---\ninsert_stmt: \"INSERT\"i \"INTO\"i CNAME [\"(\" column_name_list \")\"] \"VALUES\"i \"(\" value_list \")\"\ncolumn_name_list: CNAME (\",\" CNAME)*\nvalue_list: literal (\",\" literal)*\n\n// --- UPDATE STATEMENT ---\nupdate_stmt: \"UPDATE\"i CNAME \"SET\"i set_assignment (\",\" set_assignment)* [where_clause]\nset_assignment: CNAME \"=\" literal\n\n// --- DELETE STATEMENT ---\ndelete_stmt: \"DELETE\"i \"FROM\"i CNAME [where_clause]\n\n// --- TERMINALS ---\nAGG_FUNC.2: /(?i:COUNT|SUM|AVG|MIN|MAX)/\nCOMP_OP.2: \"<=\" | \">=\" | \"!=\" | \"<>\" | \"=\" | \"<\" | \">\"\n\n%import common.CNAME\n%import common.NUMBER\nSTRING: /'([^'\\\\]|\\\\.)*'/\n%import common.WS\n%ignore WS\n";

